&lt;li style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt;
&lt;p id=&quot;p-rc_9f54a0704e3d2953-57&quot; data-path-to-node=&quot;5,12,0&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt;&lt;span data-path-to-node=&quot;5,12,0,0&quot;&gt;&lt;span class=&quot;citation-4360 citation-end-4360&quot;&gt;Help build a high-functioning design te&lt;sup class=&quot;superscript&quot; data-turn-source-index=&quot;25&quot;&gt;&lt;/sup&gt;&lt;/span&gt;am and culture; contributing to hiring processes, providing thoughtful feedback in design critiques, identifying internal and external opportunities to level up design at Geotab&lt;/span&gt;&lt;span data-path-to-node=&quot;5,12,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;5,12,0,2&quot;&gt;.&lt;/span&gt; &lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h1&gt;&lt;span style=&quot;color: rgb(37, 71, 123);&quot;&gt;What you&#39;ll bring to the role:&lt;/span&gt;&lt;/h1&gt;
&lt;div class=&quot;MuiGrid-root css-17v2lcf&quot;&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt;
&lt;p id=&quot;p-rc_9f54a0704e3d2953-58&quot; data-path-to-node=&quot;7,0,0&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt;&lt;span data-path-to-node=&quot;7,0,0,0&quot;&gt;5-8 years of relevant industry experience&lt;/span&gt;&lt;span data-path-to-node=&quot;7,0,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;7,0,0,2&quot;&gt;.&lt;/span&gt; &lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt;
